import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Build target state lookup
    targets = {}
    for row in target_state.itertuples(index=False):
        targets[row.order_id] = {
            "status": row.status,
            "amount": row.amount,
            "last_seq": row.last_seq,
        }

    # Deduplicate events by seq (at-least-once delivery -> apply once)
    events = cdc_events.drop_duplicates(subset="seq").copy()
    events = events.sort_values(["order_id", "seq"])

    # Collect all order ids to process: those in target_state or in events
    all_order_ids = set(targets.keys()) | set(events["order_id"].unique().tolist())

    # Group events by order_id for quick access
    events_by_order = {
        oid: grp.sort_values("seq")
        for oid, grp in events.groupby("order_id")
    }

    new_state_rows = []
    tombstone_rows = []

    for oid in all_order_ids:
        has_initial = oid in targets
        if has_initial:
            current_exists = True
            current_status = targets[oid]["status"]
            current_amount = targets[oid]["amount"]
            current_last_seq = targets[oid]["last_seq"]
            guard_seq = targets[oid]["last_seq"]
        else:
            current_exists = False
            current_status = None
            current_amount = None
            current_last_seq = None
            guard_seq = None

        grp = events_by_order.get(oid)

        last_applied_seq = None
        last_applied_op = None

        if grp is not None:
            if has_initial:
                grp = grp[grp["seq"] > guard_seq]

            for ev in grp.itertuples(index=False):
                op = ev.op
                seq = ev.seq
                status = ev.status
                amount = ev.amount

                if op in ("I", "U"):
                    if current_exists:
                        new_status = status
                        if op == "U" and pd.isna(amount):
                            new_amount = current_amount
                        else:
                            new_amount = amount
                    else:
                        new_status = status
                        new_amount = amount

                    current_status = new_status
                    current_amount = new_amount
                    current_exists = True
                    current_last_seq = seq
                    last_applied_seq = seq
                    last_applied_op = op

                elif op == "D":
                    if current_exists:
                        current_exists = False
                        current_status = None
                        current_amount = None
                        current_last_seq = seq
                        last_applied_seq = seq
                        last_applied_op = "D"
                    # else: skip, no-op, does not count as applied

        if current_exists:
            new_state_rows.append(
                {
                    "order_id": oid,
                    "status": current_status,
                    "amount": current_amount,
                    "last_seq": current_last_seq,
                }
            )

        if (not current_exists) and last_applied_op == "D":
            tombstone_rows.append(
                {
                    "order_id": oid,
                    "deleted_seq": last_applied_seq,
                }
            )

    new_state = pd.DataFrame(
        new_state_rows, columns=["order_id", "status", "amount", "last_seq"]
    )
    if not new_state.empty:
        new_state = new_state.sort_values("order_id").reset_index(drop=True)
        new_state["order_id"] = new_state["order_id"].astype("int64")
        new_state["last_seq"] = new_state["last_seq"].astype("int64")
        new_state["amount"] = new_state["amount"].astype("float64")
        new_state["status"] = new_state["status"].astype(object)
    else:
        new_state = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "status": pd.Series(dtype="object"),
                "amount": pd.Series(dtype="float64"),
                "last_seq": pd.Series(dtype="int64"),
            }
        )

    tombstones = pd.DataFrame(
        tombstone_rows, columns=["order_id", "deleted_seq"]
    )
    if not tombstones.empty:
        tombstones = tombstones.sort_values("order_id").reset_index(drop=True)
        tombstones["order_id"] = tombstones["order_id"].astype("int64")
        tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")
    else:
        tombstones = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "deleted_seq": pd.Series(dtype="int64"),
            }
        )

    return {"new_state": new_state, "tombstones": tombstones}
